from flask import Flask, render_template_string, jsonify, request, session, redirect
import nmap, socket, threading, hashlib
from datetime import datetime

app = Flask(__name__)
app.secret_key = "netguard_diamond_2025"

USERS = {
    "diamond": hashlib.sha256("Diamond@2025".encode()).hexdigest(),
    "admin": hashlib.sha256("Admin@2025".encode()).hexdigest(),
}

scan_results = {"devices":[],"alerts":[],"scanning":False,
                "progress":"","scan_time":"","complete":False}

def get_ml_model():
    from sklearn.ensemble import RandomForestClassifier
    import numpy as np
    np.random.seed(42)
    normal = np.column_stack([np.random.randint(50,150,500),np.random.randint(1024,65535,500),np.random.choice([80,443,53,5353],500),np.zeros(500),np.zeros(500),np.zeros(500),np.zeros(500),np.zeros(500)])
    attack = np.column_stack([np.random.choice([40,500,1000],1500),np.random.randint(1024,65535,1500),np.full(1500,80),np.ones(1500),np.zeros(1500),np.zeros(1500),np.zeros(1500),np.ones(1500)])
    data = np.vstack([normal,attack])
    from sklearn.ensemble import RandomForestClassifier
    clf = RandomForestClassifier(n_estimators=100,random_state=42)
    clf.fit(data[:,:7],data[:,7])
    return clf

MODEL = None
def load_model():
    global MODEL
    MODEL = get_ml_model()
threading.Thread(target=load_model,daemon=True).start()

def get_local_ip():
    try:
        s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM)
        s.connect(("8.8.8.8",80))
        ip=s.getsockname()[0]
        s.close()
        return ip
    except: return "192.168.0.1"

def get_hostname(ip):
    try: return socket.gethostbyaddr(ip)[0]
    except: return ""

def identify_device(ip,hostname,ports,mac=""):
    h=hostname.lower()
    local_ip=get_local_ip()
    if ip==local_ip or any(x in h for x in ["iot-lab","raspberry","pi"]): return "Raspberry Pi","#22c55e","security"
    if mac.upper().startswith("EC:75:0C") or ip.endswith(".1"): return "Router / Gateway","#ef4444","router"
    if mac.upper().startswith("DC:23:52") or any(x in h for x in ["tuya","bulb"]): return "Smart Bulb","#f59e0b","bulb"
    if any(x in h for x in ["android","oppo","samsung","iphone","phone"]): return "Smartphone","#3b82f6","phone"
    if any(x in h for x in ["laptop","desktop","legion","hp","dell"]): return "Computer","#3b82f6","computer"
    if any(x in h for x in ["camera","cam","hikvision"]): return "IP Camera","#ef4444","camera"
    if any(x in h for x in ["tv","television"]): return "Smart TV","#f59e0b","tv"
    if 22 in ports and 80 not in ports: return "Linux Device","#3b82f6","linux"
    if 80 in ports or 443 in ports: return "Network Device","#ef4444","router"
    return "Unknown Device","#94a3b8","unknown"

def assess_risk(ports):
    score=0; vulns=[]
    if 23 in ports:
        score+=40
        vulns.append({"port":23,"severity":"CRITICAL","service":"Telnet","detail":"Telnet open - Mirai botnet entry point","fix":"Disable Telnet immediately"})
    if 80 in ports:
        score+=30
        vulns.append({"port":80,"severity":"CRITICAL","service":"HTTP Admin","detail":"Unencrypted admin panel - brute force risk","fix":"Change default password and enable account lockout"})
    if 1900 in ports:
        score+=20
        vulns.append({"port":1900,"severity":"WARNING","service":"UPnP","detail":"UPnP enabled - exploitable remotely","fix":"Disable UPnP in router settings"})
    if 22 in ports:
        score+=10
        vulns.append({"port":22,"severity":"WARNING","service":"SSH","detail":"SSH open - brute force risk","fix":"Use key-based authentication"})
    if 8080 in ports:
        score+=10
        vulns.append({"port":8080,"severity":"WARNING","service":"HTTP Alt","detail":"Alternate HTTP port open","fix":"Close port 8080 if not needed"})
    if score==0: label,color="Safe","#22c55e"
    elif score<25: label,color="Low","#f59e0b"
    elif score<55: label,color="Medium","#f59e0b"
    else: label,color="High","#ef4444"
    return min(score,100),label,color,vulns

def generate_alerts(devices):
    alerts=[]
    for d in devices:
        ports=d.get("open_ports",[]); ip=d.get("ip",""); dtype=d.get("type","")
        if 23 in ports: alerts.append({"rule_id":1000005,"severity":"CRITICAL","device":ip,"name":"Telnet Open - Botnet Risk","fix":"Disable Telnet immediately","time":datetime.now().strftime("%H:%M:%S")})
        if 80 in ports: alerts.append({"rule_id":1000001,"severity":"CRITICAL","device":ip,"name":"HTTP Admin Panel - Brute Force Risk","fix":"Change default password and enable account lockout","time":datetime.now().strftime("%H:%M:%S")})
        if 1900 in ports: alerts.append({"rule_id":9000001,"severity":"WARNING","device":ip,"name":"UPnP Enabled - Privacy Risk","fix":"Disable UPnP in router settings","time":datetime.now().strftime("%H:%M:%S")})
        if "bulb" in dtype.lower(): alerts.append({"rule_id":2000001,"severity":"WARNING","device":ip,"name":"Smart Bulb - Privacy Leakage","fix":"Create separate IoT guest network","time":datetime.now().strftime("%H:%M:%S")})
        if "camera" in dtype.lower(): alerts.append({"rule_id":2000002,"severity":"CRITICAL","device":ip,"name":"IP Camera - High Privacy Risk","fix":"Move camera to isolated IoT network","time":datetime.now().strftime("%H:%M:%S")})
    return alerts

def ml_classify(port):
    if MODEL is None: return "Analysing",0
    import numpy as np
    pred=MODEL.predict([[64,12345,port,1,0,0,0]])[0]
    prob=MODEL.predict_proba([[64,12345,port,1,0,0,0]])[0]
    return ("Attack" if pred==1 else "Normal"),round(max(prob)*100,1)

def run_scan(subnet):
    global scan_results
    scan_results.update({"scanning":True,"complete":False,"devices":[],"alerts":[],"progress":f"Scanning {subnet}..."})
    nm=nmap.PortScanner()
    try:
        nm.scan(hosts=subnet,arguments="-sn --send-ip -T4")
        hosts=nm.all_hosts()
        scan_results["progress"]=f"Found {len(hosts)} devices. Analysing..."
    except Exception as e:
        scan_results.update({"progress":f"Error: {e}","scanning":False}); return
    devices=[]
    for i,ip in enumerate(hosts):
        scan_results["progress"]=f"Scanning {i+1}/{len(hosts)}: {ip}"
        hostname=get_hostname(ip); mac=""
        try: mac=nm[ip]["addresses"].get("mac","")
        except: pass
        open_ports,services=[],{}
        try:
            nm.scan(ip,"20-25,53,80,443,1900,8080,8443","-sV --open -T4")
            if ip in nm.all_hosts():
                for proto in nm[ip].all_protocols():
                    for port in nm[ip][proto].keys():
                        if nm[ip][proto][port]["state"]=="open":
                            open_ports.append(port)
                            services[str(port)]=nm[ip][proto][port].get("name","unknown")
        except: pass
        dtype,dcolor,dicon=identify_device(ip,hostname,open_ports,mac)
        risk_score,risk_label,risk_color,vulns=assess_risk(open_ports)
        ml_result,ml_conf=ml_classify(open_ports[0] if open_ports else 443)
        devices.append({"ip":ip,"hostname":hostname or ip,"mac":mac or "N/A","type":dtype,"color":dcolor,"icon":dicon,"open_ports":open_ports,"services":services,"risk_score":risk_score,"risk_label":risk_label,"risk_color":risk_color,"vulnerabilities":vulns,"ml_result":ml_result,"ml_confidence":ml_conf,"scan_time":datetime.now().strftime("%H:%M:%S")})
    alerts=generate_alerts(devices)
    scan_results.update({"devices":devices,"alerts":alerts,"scan_time":datetime.now().strftime("%d %b %Y %H:%M:%S"),"progress":f"Complete - {len(devices)} devices, {len(alerts)} alerts","scanning":False,"complete":True})

