@app.route("/")
def index():
    if "user" not in session: return redirect("/login")
    return render_template_string(DASH_HTML, username=session["user"])

@app.route("/login", methods=["GET","POST"])
def login():
    error=None
    if request.method=="POST":
        username=request.form.get("username","").strip().lower()
        password=request.form.get("password","")
        hashed=hashlib.sha256(password.encode()).hexdigest()
        if username in USERS and USERS[username]==hashed:
            session["user"]=username
            return redirect("/")
        error="Invalid username or password. Please try again."
    return render_template_string(LOGIN_HTML, error=error)

@app.route("/logout")
def logout():
    session.clear()
    return redirect("/login")

@app.route("/scan", methods=["POST"])
def scan():
    if "user" not in session: return jsonify({"status":"not_logged_in"})
    global scan_results
    if scan_results["scanning"]: return jsonify({"status":"already_running"})
    data=request.get_json()
    subnet=data.get("subnet","192.168.0.0/24")
    scan_results["complete"]=False
    threading.Thread(target=run_scan,args=(subnet,),daemon=True).start()
    return jsonify({"status":"started"})

@app.route("/results")
def results():
    if "user" not in session: return jsonify({"status":"not_logged_in"})
    return jsonify(scan_results)

@app.route("/clear", methods=["POST"])
def clear():
    global scan_results
    scan_results={"devices":[],"alerts":[],"scanning":False,"progress":"Cleared","scan_time":"","complete":False}
    return jsonify({"status":"cleared"})

